using Xunit;
using System.Net;
using System.Net.Http.Json;
using CoracaoAnimal.Core;
using CoracaoAnimal.Client;
using Microsoft.AspNetCore.Mvc.Testing;
using Microsoft.AspNetCore.Hosting;
using Microsoft.Extensions.Configuration;
namespace CoracaoAnimal.Tests;
public sealed class Factory:WebApplicationFactory<Program>{readonly string path=Path.Combine(Path.GetTempPath(),Guid.NewGuid()+".db");protected override void ConfigureWebHost(IWebHostBuilder b){b.UseEnvironment("Testing");b.ConfigureAppConfiguration((_,c)=>c.AddInMemoryCollection(new Dictionary<string,string?>{{"Database:Provider","Sqlite"},{"Database:Initialize","true"},{"ConnectionStrings:CoracaoAnimal","Data Source="+path},{"Bootstrap:Email","admin@example.test"},{"Bootstrap:Password","Test-only-Password-987!"}}));}public HttpClient Client(){var c=CreateClient(new(){BaseAddress=new Uri("https://localhost"),AllowAutoRedirect=false});c.DefaultRequestHeaders.Add("X-CSRF","1");return c;}protected override void Dispose(bool disposing){base.Dispose(disposing);if(disposing){Microsoft.Data.Sqlite.SqliteConnection.ClearAllPools();File.Delete(path);}}}
public class IntegrationTests {
 static string Cpf(){var digits=Enumerable.Range(0,9).Select(_=>Random.Shared.Next(0,10)).ToList();for(int n=10;n<=11;n++){var sum=digits.Select((v,i)=>v*(n-i)).Sum();var d=11-sum%11;digits.Add(d>=10?0:d);}return string.Concat(digits);}
 static async Task<HttpClient> Admin(Factory f,string mode="web"){var c=f.Client();var r=await c.PostAsJsonAsync("/api/auth/login",new Login("admin@example.test","Test-only-Password-987!",mode));r.EnsureSuccessStatusCode();if(mode=="app"){var s=await r.Content.ReadFromJsonAsync<SessaoDto>();c.DefaultRequestHeaders.Authorization=new("Bearer",s!.Token);}return c;}
 static async Task<HttpClient> User(Factory f,bool complete=true){var c=f.Client();var email=Guid.NewGuid()+"@example.test";(await c.PostAsJsonAsync("/api/auth/cadastro",new Cadastro("Pessoa de teste",email,"User-Test-Password-987!"))).EnsureSuccessStatusCode();(await c.PostAsJsonAsync("/api/auth/login",new Login(email,"User-Test-Password-987!"))).EnsureSuccessStatusCode();if(complete)(await c.PutAsJsonAsync("/api/me/",new PerfilInput("Pessoa de teste",Cpf(),"11999999999","Rua de teste, 123"))).EnsureSuccessStatusCode();return c;}
 static async Task<AnimalDto> Animal(HttpClient c){var r=await c.PostAsJsonAsync("/api/admin/animais",new AnimalInput("Amigo","cao","SRD",2,"medio","disponivel","Descrição de teste"));r.EnsureSuccessStatusCode();return (await r.Content.ReadFromJsonAsync<AnimalDto>())!;}
 [Fact]public async Task AdminOnlyWeb(){using var f=new Factory();using var web=await Admin(f);Assert.Equal(HttpStatusCode.OK,(await web.GetAsync("/api/admin/resumo")).StatusCode);using var app=await Admin(f,"app");Assert.Equal(HttpStatusCode.Forbidden,(await app.GetAsync("/api/admin/resumo")).StatusCode);Assert.Equal(HttpStatusCode.OK,(await app.GetAsync("/api/me/")).StatusCode);using var user=await User(f);Assert.Equal(HttpStatusCode.Forbidden,(await user.GetAsync("/api/admin/resumo")).StatusCode);}
 [Fact]public async Task CsrfAndOriginRequired(){using var f=new Factory();using var c=f.Client();c.DefaultRequestHeaders.Remove("X-CSRF");Assert.Equal(HttpStatusCode.Forbidden,(await c.PostAsJsonAsync("/api/auth/login",new Login("a@example.test","bad"))).StatusCode);c.DefaultRequestHeaders.Add("X-CSRF","1");c.DefaultRequestHeaders.Add("Origin","https://evil.example");Assert.Equal(HttpStatusCode.Forbidden,(await c.PostAsJsonAsync("/api/auth/login",new Login("a@example.test","bad"))).StatusCode);}
 [Fact]public async Task AdoptionReservesAndCannotDuplicate(){using var f=new Factory();using var admin=await Admin(f);var animal=await Animal(admin);using var a=await User(f);using var b=await User(f);Assert.Equal(HttpStatusCode.Created,(await a.PostAsJsonAsync("/api/me/adocoes",new AdocaoInput(animal.Id,"Tenho espaço",true))).StatusCode);Assert.Equal(HttpStatusCode.Conflict,(await b.PostAsJsonAsync("/api/me/adocoes",new AdocaoInput(animal.Id,"",true))).StatusCode);Assert.Equal("em_processo",(await a.GetFromJsonAsync<AnimalDto>($"/api/animais/{animal.Id}"))!.Status);}
 [Fact]public async Task AdoptionRequiresProfileAndTerms(){using var f=new Factory();using var admin=await Admin(f);var animal=await Animal(admin);using var c=await User(f,false);Assert.Equal(HttpStatusCode.BadRequest,(await c.PostAsJsonAsync("/api/me/adocoes",new AdocaoInput(animal.Id,"",true))).StatusCode);Assert.Equal(HttpStatusCode.BadRequest,(await c.PostAsJsonAsync("/api/me/adocoes",new AdocaoInput(animal.Id,"",false))).StatusCode);}
 [Fact]public async Task AdoptionIsolationAndCancellation(){using var f=new Factory();using var admin=await Admin(f);var animal=await Animal(admin);using var a=await User(f);using var b=await User(f);var r=await a.PostAsJsonAsync("/api/me/adocoes",new AdocaoInput(animal.Id,"",true));var d=(await r.Content.ReadFromJsonAsync<AdocaoDto>())!;Assert.Empty((await b.GetFromJsonAsync<List<AdocaoDto>>("/api/me/adocoes"))!);Assert.Equal(HttpStatusCode.NotFound,(await b.PostAsync($"/api/me/adocoes/{d.Id}/cancelar",null)).StatusCode);(await a.PostAsync($"/api/me/adocoes/{d.Id}/cancelar",null)).EnsureSuccessStatusCode();Assert.Equal("disponivel",(await a.GetFromJsonAsync<AnimalDto>($"/api/animais/{animal.Id}"))!.Status);}
 [Fact]public async Task AdoptionMustBeApprovedBeforeCompletion(){using var f=new Factory();using var admin=await Admin(f);var animal=await Animal(admin);using var a=await User(f);var r=await a.PostAsJsonAsync("/api/me/adocoes",new AdocaoInput(animal.Id,"",true));var d=(await r.Content.ReadFromJsonAsync<AdocaoDto>())!;Assert.Equal(HttpStatusCode.Conflict,(await admin.PutAsJsonAsync($"/api/admin/adocoes/{d.Id}/status",new StatusInput("concluida"))).StatusCode);(await admin.PutAsJsonAsync($"/api/admin/adocoes/{d.Id}/status",new StatusInput("aprovada"))).EnsureSuccessStatusCode();(await admin.PutAsJsonAsync($"/api/admin/adocoes/{d.Id}/status",new StatusInput("concluida"))).EnsureSuccessStatusCode();Assert.Equal("adotado",(await a.GetFromJsonAsync<AnimalDto>($"/api/animais/{animal.Id}"))!.Status);Assert.Equal(HttpStatusCode.Conflict,(await a.PostAsync($"/api/me/adocoes/{d.Id}/cancelar",null)).StatusCode);}
 [Fact]public async Task DonationStartsPendingAndIsIsolated(){using var f=new Factory();using var a=await User(f);using var b=await User(f);var r=await a.PostAsJsonAsync("/api/me/doacoes",new DoacaoInput(25.50m,"pix","",false));r.EnsureSuccessStatusCode();var d=(await r.Content.ReadFromJsonAsync<DoacaoDto>())!;Assert.Equal("pendente",d.Status);Assert.Empty((await b.GetFromJsonAsync<List<DoacaoDto>>("/api/me/doacoes"))!);Assert.Equal(HttpStatusCode.NotFound,(await b.PostAsync($"/api/me/doacoes/{d.Id}/cancelar",null)).StatusCode);using var admin=await Admin(f);(await admin.PutAsJsonAsync($"/api/admin/doacoes/{d.Id}/status",new StatusInput("confirmada"))).EnsureSuccessStatusCode();Assert.Equal(HttpStatusCode.Conflict,(await a.PostAsync($"/api/me/doacoes/{d.Id}/cancelar",null)).StatusCode);}
 [Fact]public async Task PasswordRevokesSessions(){using var f=new Factory();using var c=await User(f);(await c.PutAsJsonAsync("/api/me/senha",new SenhaInput("User-Test-Password-987!","New-Test-Password-123!"))).EnsureSuccessStatusCode();Assert.Equal(HttpStatusCode.Unauthorized,(await c.GetAsync("/api/me/")).StatusCode);}
 [Fact]public async Task LogoutRevokesSession(){using var f=new Factory();using var c=await User(f);(await c.PostAsync("/api/auth/logout",null)).EnsureSuccessStatusCode();Assert.Equal(HttpStatusCode.Unauthorized,(await c.GetAsync("/api/me/")).StatusCode);}
 [Fact]public async Task VolunteerUpsertKeepsOneRecord(){using var f=new Factory();using var c=await User(f);var first=await c.PutAsJsonAsync("/api/me/voluntariado",new VoluntarioInput("Passeios","Sábados"));var a=(await first.Content.ReadFromJsonAsync<VoluntarioDto>())!;var second=await c.PutAsJsonAsync("/api/me/voluntariado",new VoluntarioInput("Transporte","Domingos"));Assert.Equal(a.Id,(await second.Content.ReadFromJsonAsync<VoluntarioDto>())!.Id);(await c.DeleteAsync("/api/me/voluntariado")).EnsureSuccessStatusCode();Assert.Equal("inativo",(await c.GetFromJsonAsync<VoluntarioDto>("/api/me/voluntariado"))!.Status);}
 [Fact]public async Task RejectsFakeImage(){using var f=new Factory();using var c=await Admin(f);var a=await Animal(c);using var form=new MultipartFormDataContent();var content=new ByteArrayContent(System.Text.Encoding.UTF8.GetBytes("<script>alert(1)</script>"));content.Headers.ContentType=new("image/png");form.Add(content,"foto","fake.png");Assert.Equal(HttpStatusCode.BadRequest,(await c.PostAsync($"/api/admin/animais/{a.Id}/foto",form)).StatusCode);}
 [Theory][InlineData("https://example.com",true)][InlineData("http://localhost:5080",true)][InlineData("http://10.0.2.2:5080",true)][InlineData("http://public.example",false)][InlineData("https://user:password@example.com",false)][InlineData("https://example.com/path",false)]public void ClientUrlPolicy(string url,bool allowed){if(allowed)Assert.NotNull(ApiClient.ValidateUrl(url));else Assert.Throws<InvalidOperationException>(()=>ApiClient.ValidateUrl(url));}
}
